use std::{collections::VecDeque, future::Future};

pub async fn transfer(
    source: &mut VecDeque<u8>,
    destination: &mut Vec<u8>,
    ready: impl Future<Output = ()>,
) {
    let item = source.pop_front();
    ready.await;
    if let Some(item) = item {
        destination.push(item);
    }
}

