use cancellation_eval::transfer;
use std::{collections::VecDeque, future::{pending, ready, Future}, sync::Arc, task::{Context, Poll, Wake, Waker}};

struct Noop;
impl Wake for Noop {
    fn wake(self: Arc<Self>) {}
}

#[test]
fn cancelling_while_pending_preserves_both_collections() {
    let mut source = VecDeque::from([7, 8]);
    let mut destination = vec![9];
    let mut operation = Box::pin(transfer(&mut source, &mut destination, pending()));
    let waker = Waker::from(Arc::new(Noop));
    assert!(operation.as_mut().poll(&mut Context::from_waker(&waker)).is_pending());
    drop(operation);
    assert_eq!(source, VecDeque::from([7, 8]));
    assert_eq!(destination, vec![9]);
}

#[test]
fn completion_moves_one_item() {
    let mut source = VecDeque::from([7, 8]);
    let mut destination = vec![9];
    let mut operation = Box::pin(transfer(&mut source, &mut destination, ready(())));
    let waker = Waker::from(Arc::new(Noop));
    assert_eq!(operation.as_mut().poll(&mut Context::from_waker(&waker)), Poll::Ready(()));
    drop(operation);
    assert_eq!(source, VecDeque::from([8]));
    assert_eq!(destination, vec![9, 7]);
}

